// Layer 2: Dense (32 -> 2)
static const float L2_WEIGHTS[64] = {-0.03130724f, -0.01342121f, 0.01293855f, 0.00898542f, 0.02829889f, 0.04058827f, 0.01651997f, 0.00512358f, 0.11907823f, 0.08787087f, -0.00955289f, -0.02567992f, 0.06867243f, 0.08924908f, -0.04823592f, -0.06793793f, -0.07806388f, -0.05906084f, 0.07976680f, 0.06516603f, 0.03197325f, 0.06016965f, -0.03454351f, -0.03063531f, 0.02418132f, 0.05495032f, -0.02853116f, -0.01723959f, -0.01769178f, -0.03972830f, -0.13738218f, -0.10597153f, 0.07848541f, 0.02380701f, -0.07187028f, -0.03385167f, -0.08682493f, -0.09709879f, 0.11793815f, 0.06637493f, -0.10750233f, -0.08728347f, 0.07691955f, 0.04141301f, -0.05998203f, -0.00550447f, -0.01200379f, 0.05831366f, -0.00462500f, -0.03930509f, -0.05092891f, -0.09808420f, -0.00628009f, -0.02181228f, -0.11714359f, -0.13837065f, 0.03452073f, 0.08587275f, -0.08779557f, -0.03805072f, 0.08387384f, 0.07292555f, -0.09131450f, -0.04016521f};
static const float L2_BIASES[2] = {-0.01401065f, -0.02076924f};

// Performs forward inference without dynamic memory allocation
static inline void actor_forward(const float input[4], float output[2]) {
    float buf_a[32];
    float buf_b[32];
    float* tmp; // Declared once at function level
    
    // Copy input into initial working buffer
    for (int i = 0; i < 4; i++) {
        buf_a[i] = input[i];
    }

    float* src = buf_a;
    float* dst = buf_b;

    // --- Layer 0 Execution ---
    for (int j = 0; j < 32; j++) {
        float sum = L0_BIASES[j];
        for (int k = 0; k < 4; k++) {
            sum += src[k] * L0_WEIGHTS[k * 32 + j];
        }
        dst[j] = tanhf(sum);
    }
    tmp = src; src = dst; dst = tmp;

    // --- Layer 1 Execution ---
    for (int j = 0; j < 32; j++) {
        float sum = L1_BIASES[j];
        for (int k = 0; k < 32; k++) {
            sum += src[k] * L1_WEIGHTS[k * 32 + j];
        }
        dst[j] = tanhf(sum);
    }
    tmp = src; src = dst; dst = tmp;

    // --- Layer 2 Execution ---
    for (int j = 0; j < 2; j++) {
        float sum = L2_BIASES[j];
        for (int k = 0; k < 32; k++) {
            sum += src[k] * L2_WEIGHTS[k * 2 + j];
        }
        dst[j] = sum;
    }

    // Copy final activation output to user buffer
    for (int i = 0; i < 2; i++) {
        output[i] = dst[i];
    }
}

